import { serve } from "https://deno.land/std@0.224.0/http/server.ts";

const SUPABASE_URL = Deno.env.get("SUPABASE_URL")!;
const SERVICE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
const X_TOKEN = Deno.env.get("X_BEARER_TOKEN")!;

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
    "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
      "Access-Control-Allow-Methods": "GET, POST, OPTIONS",
      };

      function response(data: unknown, status = 200) {
        return new Response(JSON.stringify(data), {
            status,
                headers: {
                      ...corsHeaders,
                            "Content-Type": "application/json",
                                },
                                  });
                                  }

async function dbRequest(path: string, options: RequestInit = {}) {
                                    return fetch(`${SUPABASE_URL}/rest/v1/${path}`, {
                                        ...options,
                                            headers: {
                                                  apikey: SERVICE_KEY,
                                                        Authorization: `Bearer ${SERVICE_KEY}`,
                                                              "Content-Type": "application/json",
                                                                    ...options.headers,
                                                                        },
                                                                          });
                                                                          }

                                                                          serve(async (req) => {
                                                                            if (req.method === "OPTIONS") {
                                                                                return new Response("ok", { headers: corsHeaders });
                                                                                  }

                                                                                    try {
                                                                                        if (!SUPABASE_URL || !SERVICE_KEY || !X_TOKEN) {
                                                                                              return response({ error: "Server secrets belum lengkap." }, 500);
                                                                                                  }

                                                                                                      if (req.method === "GET") {
                                                                                                            const [hashtagsRes, postsRes] = await Promise.all([
                                                                                                                    dbRequest("hashtags?select=*&order=created_at.desc"),
                                                                                                                            dbRequest("monitored_posts?select=*&order=posted_at.desc&limit=100"),
                                                                                                                                  ]);

                                                                                                                                        if (!hashtagsRes.ok || !postsRes.ok) {
                                                                                                                                                return response({ error: "Gagal membaca database." }, 500);
                                                                                                                                                      }

                                                                                                                                                            return response({
                                                                                                                                                                    hashtags: await hashtagsRes.json(),
                                                                                                                                                                            posts: await postsRes.json(),
                                                                                                                                                                                  });
                                                                                                                                                                                      }

                                                                                                                                                                                          if (req.method !== "POST") {
                                                                                                                                                                                                return response({ error: "Method tidak diizinkan." }, 405);
                                                                                                                                                                                                    }

                                                                                                                                                                                                        const body = await req.json();

                                                                                                                                                                                                                          // TAMBAH HASHTAG
                                                                                                                                                                                                                              if (body.action === "add") {
                                                                                                                                                                                                                                    const tag = String(body.tag || "")
                                                                                                                                                                                                                                            .trim()
                                                                                                                                                                                                                                                    .replace(/^#/, "");

                                                                                                                                                                                                                                                          if (!/^[\p{L}\p{N}_]{1,100}$/u.test(tag)) {
                                                                                                                                                                                                                                                                  return response({ error: "Format hashtag tidak valid." }, 400);
                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                              const result = await dbRequest("hashtags", {
                                                                                                                                                                                                                                                                                      method: "POST",
                                                                                                                                                                                                                                                                                              headers: {
                                                                                                                                                                                                                                                                                                        Prefer: "return=representation",
                                                                                                                                                                                                                                                                                                                },
                                                                                                                                                                                                                                                                                                                        body: JSON.stringify({ tag }),
                                                                                                                                                                                                                                                                                                                              });

                                                                                                                                                                                                                                                                                                                                    const data = await result.json();

                                                                                                                                                                                                                                                                                                                                          if (!result.ok) {
                                                                                                                                                                                                                                                                                                                                                  return response({ error: "Hashtag gagal ditambahkan.", details: data }, result.status);
                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                              return response({ success: true, data });
                                                                                                                                                                                                                                                                                                                                                                  }

                                                                                                                                                                                                                                                                                                                                                                      // HAPUS HASHTAG
                                                                                                                                                                                                                                                                                                                                                                          if (body.action === "delete") {
                                                                                                                                                                                                                                                                                                                                                                                if (!body.id) {
                                                                                                                                                                                                                                                                                                                                                                                        return response({ error: "ID hashtag diperlukan." }, 400);
                                                                                                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                                                                                                                    const result = await dbRequest(
                                                                                                                                                                                                                                                                                                                                                                                                            `hashtags?id=eq.${encodeURIComponent(body.id)}`,
                                                                                                                                                                                                                                                                                                                                                                                                                    { method: "DELETE" },
                                                                                                                                                                                                                                                                                                                                                                                                                          );

                                                                                                                                                                                                                                                                                                                                                                                                                                if (!result.ok) {
                                                                                                                                                                                                                                                                                                                                                                                                                                        return response({ error: "Gagal menghapus hashtag." }, 500);
                                                                                                                                                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                                                                                                                                                                    return response({ success: true });
                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                            // AMBIL POSTINGAN TERBARU DARI X
                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (body.action === "sync") {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const tagsRes = await dbRequest(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                              "hashtags?select=tag&order=created_at.asc&limit=10",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          if (!tagsRes.ok) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  return response({ error: "Gagal mengambil daftar hashtag." }, 500);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const tags = await tagsRes.json();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const results = [];

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          for (const item of tags) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const query = `#${item.tag}`;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const params = new URLSearchParams({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    query,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              max_results: "100",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        "tweet.fields": "created_at,author_id,public_metrics",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  expansions: "author_id",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            "user.fields": "name,username,profile_image_url",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const xRes = await fetch(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      `https://api.x.com/2/tweets/search/recent?${params}`,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            headers: {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          Authorization: `Bearer ${X_TOKEN}`,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (!xRes.ok) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const error = await xRes.text();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    results.push({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                hashtag: item.tag,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            success: false,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        error,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    status: xRes.status,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        continue;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const xData = await xRes.json();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const users = new Map(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          (xData.includes?.users || []).map((u: any) => [u.id, u]),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const posts = (xData.data || []).map((post: any) => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const user: any = users.get(post.author_id);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              return {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          x_post_id: post.id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      hashtag: item.tag,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  author_username: user?.username || "",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              author_name: user?.name || "",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          post_text: post.text,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      posted_at: post.created_at || null,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  post_url: user?.username
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ? `https://x.com/${user.username}/status/${post.id}`
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              : `https://x.com/i/web/status/${post.id}`,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        };
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (posts.length > 0) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const saveRes = await dbRequest(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              "monitored_posts?on_conflict=x_post_id",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        method: "POST",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      headers: {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      Prefer: "resolution=merge-duplicates,return=minimal",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  body: JSON.stringify(posts),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  results.push({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              hashtag: item.tag,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          success: saveRes.ok,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      detected: posts.length,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        } else {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  results.push({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              hashtag: item.tag,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          success: true,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      detected: 0,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return response({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            success: true,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    results,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            synced_at: new Date().toISOString(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          return response({ error: "Action tidak dikenal." }, 400);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            } catch (error) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                return response({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      error: "Terjadi kesalahan pada server.",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            details: String(error),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }, 500);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  });